-- Expand booklet lessons 1–2. Guard the input snapshot, and preserve senses/references.
CREATE TABLE g12_guard (ok INTEGER CHECK(ok=1));
CREATE TABLE g12_positions(id TEXT PRIMARY KEY,section_key TEXT,sort_order INTEGER);
CREATE TABLE IF NOT EXISTS idiom_revision_backup (revision TEXT NOT NULL,object_key TEXT NOT NULL,snapshot TEXT NOT NULL,PRIMARY KEY(revision,object_key));
INSERT OR IGNORE INTO idiom_revision_backup SELECT '0046','sections',json_group_array(json_object('key',section_key,'subtitle',subtitle,'chapter',chapter_key,'chapterSubtitle',chapter_subtitle,'chapterOrder',chapter_order,'order',sort_order,'group',group_key,'groupSubtitle',group_subtitle,'groupOrder',group_order)) FROM idiom_sections WHERE list_id='crossover-v3' HAVING count(*)>0;
INSERT OR IGNORE INTO idiom_revision_backup SELECT '0046',id,json_object('phrase',phrase,'section',section_key,'order',sort_order) FROM idioms WHERE list_id='crossover-v3';
INSERT OR IGNORE INTO idiom_revision_backup SELECT '0046','sense-'||id,json_object('idiom',idiom_id,'meaning',meaning,'order',sort_order) FROM idiom_senses WHERE idiom_id IN ('crossover-idiom-e37f67cc157cf7b5f97f5067','crossover-idiom-97e2318ec81488eb9693f9aa','crossover-idiom-5739716b01c5bfcd03b4e05d','crossover-idiom-297f99122ae6c685d062396c');
UPDATE idioms SET section_key=(SELECT section_key FROM g12_positions WHERE id=idioms.id),sort_order=(SELECT sort_order FROM g12_positions WHERE id=idioms.id),updated_at=datetime('now') WHERE list_id='crossover-v3' AND id IN (SELECT id FROM g12_positions);
UPDATE idiom_senses SET idiom_id='crossover-idiom-97e2318ec81488eb9693f9aa',sort_order=sort_order+(SELECT COALESCE(MAX(sort_order),-1)+1 FROM idiom_senses WHERE idiom_id='crossover-idiom-97e2318ec81488eb9693f9aa') WHERE idiom_id='crossover-idiom-e37f67cc157cf7b5f97f5067';
DELETE FROM idioms WHERE id='crossover-idiom-e37f67cc157cf7b5f97f5067';
UPDATE idiom_senses SET idiom_id='crossover-idiom-297f99122ae6c685d062396c',sort_order=sort_order+(SELECT COALESCE(MAX(sort_order),-1)+1 FROM idiom_senses WHERE idiom_id='crossover-idiom-297f99122ae6c685d062396c') WHERE idiom_id='crossover-idiom-5739716b01c5bfcd03b4e05d';
DELETE FROM idioms WHERE id='crossover-idiom-5739716b01c5bfcd03b4e05d';
UPDATE idioms SET phrase='ask A B / ask B of A' WHERE id='grammar-idiom-1687c1994eb5cd81ba0a' AND phrase='ask B of A';
UPDATE idioms SET phrase='object to O / Ving' WHERE id='grammar-idiom-db6db350d7f261ebd0e0' AND phrase='object to Ving';
DELETE FROM idiom_sections WHERE list_id='crossover-v3' AND NOT EXISTS(SELECT 1 FROM idioms WHERE list_id=idiom_sections.list_id AND section_key=idiom_sections.section_key);
DROP TABLE g12_positions;
DROP TABLE g12_guard;
